{"path": "blocos.py", "content": "def dividir(lista, n):
    if n <= 0:
        raise ValueError('n deve ser maior que zero')

    resultados = []
    for i in range(0, len(lista), n):
        resultados.append(lista[i:i + n])

    return resultados"}

